class Circle {
private:
    double radius;
    bool hasRadius;
public:
    void init() {
        radius = 0;
        hasRadius = false;
    }
    bool setRadius(double r) {
        if (r <= 0) {
            return false;
        }
        radius = r;
        hasRadius = true;
        return true;
    }
    bool ready() {
        return hasRadius;
    }
    double area() {
        return 3.14159 * radius * radius;
    }
};

int main() {
    Circle c;
    c.init();
    double r1, r2, r3;
    cin >> r1 >> r2 >> r3;
    cout << "Radius " << r1 << ": " << (c.setRadius(r1) ? "Accepted" : "Rejected") << endl;
    cout << "Radius " << r2 << ": " << (c.setRadius(r2) ? "Accepted" : "Rejected") << endl;
    cout << "Radius " << r3 << ": " << (c.setRadius(r3) ? "Accepted" : "Rejected") << endl;
    if (c.ready()) {
        cout << fixed << setprecision(2) << "Area: " << c.area() << endl;
    } else {
        cout << "No valid radius" << endl;
    }
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class LibraryMember {
private:
    string name;
    int borrowed;
public:
    void setName(string n) {
        name = n;
    }
    void reset() {
        borrowed = 0;
    }
    bool borrowBook() {
        if (borrowed >= 5) {
            return false;
        }
        borrowed = borrowed + 1;
        return true;
    }
    bool returnBook() {
        if (borrowed <= 0) {
            return false;
        }
        borrowed = borrowed - 1;
        return true;
    }
    int getBorrowed() {
        return borrowed;
    }
    string getName() {
        return name;
    }
};

int main() {
    LibraryMember m;
    string name;
    cin >> name;
    m.setName(name);
    m.reset();
    cout << "Member: " << m.getName() << endl;
    for (int i = 0; i < 5; i++) {
        char cmd;
        cin >> cmd;
        if (cmd == 'B') {
            if (m.borrowBook()) {
                cout << "Borrow OK, now " << m.getBorrowed() << endl;
            } else {
                cout << "Borrow denied, now " << m.getBorrowed() << endl;
            }
        } else {
            if (m.returnBook()) {
                cout << "Return OK, now " << m.getBorrowed() << endl;
            } else {
                cout << "Return denied, now " << m.getBorrowed() << endl;
            }
        }
    }
    cout << "Final count: " << m.getBorrowed() << endl;
    return 0;
}

#include <iostream>
#include <iomanip>
using namespace std;

class Gradebook {
private:
    int marks[3];
public:
    void setMark(int index, int m) {
        marks[index] = m;
    }
    int getMark(int index) {
        return marks[index];
    }
    double getAverage() {
        return (marks[0] + marks[1] + marks[2]) / 3.0;
    }
    int getHighest() {
        int best = marks[0];
        if (marks[1] > best) {
            best = marks[1];
        }
        if (marks[2] > best) {
            best = marks[2];
        }
        return best;
    }
    bool isPass() {
        return getAverage() >= 40.0;
    }
};

int main() {
    Gradebook g;
    int m1, m2, m3;
    cin >> m1 >> m2 >> m3;
    g.setMark(0, m1);
    g.setMark(1, m2);
    g.setMark(2, m3);
    cout << "Marks: " << g.getMark(0) << " " << g.getMark(1) << " " << g.getMark(2) << endl;
    cout << fixed << setprecision(2) << "Average: " << g.getAverage() << endl;
    cout << "Highest: " << g.getHighest() << endl;
    cout << "Result: " << (g.isPass() ? "Pass" : "Fail") << endl;
    return 0;
}

#include <iostream>
#include <string>
