class VendingMachine {
private:
    int stock;
    int coins;
public:
    void init(int s) {
        stock = s;
        coins = 0;
    }
    void insertCoin(int c) {
        coins = coins + c;
    }
    int getCoins() {
        return coins;
    }
    int getStock() {
        return stock;
    }
    void selectItem() {
        if (stock <= 0) {
            cout << "Error: Out of stock" << endl;
            return;
        }
        if (coins < 2) {
            cout << "Error: Need 2 coins" << endl;
            return;
        }
        coins = coins - 2;
        stock = stock - 1;
        cout << "Dispensed, coins " << coins << ", stock " << stock << endl;
    }
};

int main() {
    VendingMachine vm;
    int stock, n;
    cin >> stock >> n;
    vm.init(stock);
    for (int i = 0; i < n; i++) {
        string cmd;
        cin >> cmd;
        if (cmd == "C") {
            int c;
            cin >> c;
            vm.insertCoin(c);
            cout << "Coins: " << vm.getCoins() << endl;
        } else {
            vm.selectItem();
        }
    }
    cout << "Left: coins " << vm.getCoins() << ", stock " << vm.getStock() << endl;
    return 0;
}

