class ATMLight {
private:
    long long balance;
public:
    void init(long long b) {
        balance = b;
    }
    void deposit(long long amt) {
        balance = balance + amt;
        cout << "Deposit " << amt << ", balance " << balance << endl;
    }
    void withdraw(long long amt) {
        if (amt > balance) {
            cout << "Withdraw " << amt << " declined, balance " << balance << endl;
        } else {
            balance = balance - amt;
            cout << "Withdraw " << amt << ", balance " << balance << endl;
        }
    }
    void printReceipt() {
        cout << "Final balance: " << balance << endl;
    }
};

int main() {
    ATMLight atm;
    long long start;
    int n;
    cin >> start >> n;
    atm.init(start);
    for (int i = 0; i < n; i++) {
        string cmd;
        long long amt;
        cin >> cmd >> amt;
        if (cmd == "D") {
            atm.deposit(amt);
        } else {
            atm.withdraw(amt);
        }
    }
    atm.printReceipt();
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Slot {
private:
    bool occupied;
    string car;
public:
    void init() {
        occupied = false;
        car = "";
    }
    bool park(string name) {
        if (occupied) {
            return false;
        }
        car = name;
        occupied = true;
        return true;
    }
    bool leave() {
        if (!occupied) {
            return false;
        }
        car = "";
        occupied = false;
        return true;
    }
    string status() {
        if (occupied) {
            return car;
        }
        return "empty";
    }
};

int main() {
    Slot slots[10];
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < 10; i++) {
        slots[i].init();
    }
    for (int i = 0; i < m; i++) {
        string cmd;
        cin >> cmd;
        if (cmd == "E") {
            int s;
            string car;
            cin >> s >> car;
            if (slots[s - 1].park(car)) {
                cout << "Car " << car << " parked in slot " << s << endl;
            } else {
                cout << "Slot " << s << " is occupied" << endl;
            }
        } else if (cmd == "L") {
            int s;
            cin >> s;
            if (slots[s - 1].leave()) {
                cout << "Slot " << s << " is free now" << endl;
            } else {
                cout << "Slot " << s << " is already empty" << endl;
            }
        } else {
            for (int k = 0; k < n; k++) {
                cout << "Slot " << (k + 1) << ": " << slots[k].status() << endl;
            }
        }
    }
    return 0;
}

#include <iostream>
using namespace std;

class QuizPlayer {
private:
    int answered;
    int correct;
    int streak;
    int bestStreak;
public:
    void init() {
        answered = 0;
        correct = 0;
        streak = 0;
        bestStreak = 0;
    }
    void answer(bool ok) {
        answered = answered + 1;
        if (ok) {
            correct = correct + 1;
            streak = streak + 1;
            if (streak > bestStreak) {
                bestStreak = streak;
            }
            cout << "Correct!" << endl;
        } else {
            streak = 0;
            cout << "Wrong!" << endl;
        }
    }
    void report() {
        cout << "Answered: " << answered << endl;
        cout << "Correct: " << correct << endl;
        cout << "Accuracy: " << (correct * 100 / answered) << "%" << endl;
        cout << "Best streak: " << bestStreak << endl;
    }
};

int main() {
    QuizPlayer p;
    p.init();
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        int a;
        cin >> a;
        p.answer(a == 1);
    }
    p.report();
    return 0;
}

